/**
 * GDPR Art. 30 — Records of Processing Activities.
 *
 * The RoPA itself is auto-generated by `/api/compliance/ropa` from agents +
 * connectors + settings. What we *check* here is whether an admin has
 * reviewed/approved it within the last 12 months. The record must reflect
 * current processing (Art. 30(1), accountability Art. 5(2)) and be available
 * to the supervisory authority on request (Art. 30(4)); the 12-month cadence
 * is product policy, not a term in the GDPR.
 */

const complianceStore = require('../../../stores/complianceStore');

module.exports = {
    id: 'GDPR-Art30-ropa-reviewed',
    regulation: 'GDPR',
    article: '30',
    severity: 'medium',
    scope: 'global',
    verification: 'attestation',
    titleKey: 'compliance.checks.gdpr_art30.title',
    descriptionKey: 'compliance.checks.gdpr_art30.desc',
    remediationKey: 'compliance.checks.gdpr_art30.fix',
    remediationLink: 'admin/compliance/ropa',
    async evaluate(orgId) {
        const settings = await complianceStore.getSettings(orgId);
        const reviewedAt = settings.ropa_reviewed_at ? new Date(settings.ropa_reviewed_at) : null;
        if (!reviewedAt) {
            return {
                status: 'warn',
                evidence: { reviewed_at: null },
                details: 'Records of Processing Activities have never been reviewed. Open Compliance → RoPA and confirm the auto-generated record.',
            };
        }
        const ageDays = (Date.now() - reviewedAt.getTime()) / 86400000;
        if (ageDays > 365) {
            return {
                status: 'fail',
                evidence: { reviewed_at: settings.ropa_reviewed_at, age_days: Math.round(ageDays) },
                details: `RoPA was last reviewed ${Math.round(ageDays)} days ago. The record must reflect your current processing (Art. 30(1), accountability Art. 5(2)) and be available to the supervisory authority on request (Art. 30(4)) — re-review.`,
            };
        }
        if (ageDays > 300) {
            return {
                status: 'warn',
                evidence: { reviewed_at: settings.ropa_reviewed_at, age_days: Math.round(ageDays) },
                details: `RoPA review is ${Math.round(ageDays)} days old — schedule the annual re-confirmation.`,
            };
        }
        return {
            status: 'pass',
            evidence: { reviewed_at: settings.ropa_reviewed_at, age_days: Math.round(ageDays), reviewer: settings.ropa_reviewed_by || null },
            details: `RoPA last reviewed ${Math.round(ageDays)} days ago.`,
        };
    },
};
